let LANG='de';
function t(k,v){const d=I18N[LANG]||I18N.de;let s=d[k];if(s==null)s=I18N.de[k];if(s==null)return k;return typeof s==='function'?s(v||{}):v?s.replace(/\{(\w+)\}/g,(m,q)=>v[q]!=null?v[q]:m):s}
function applyLang(){document.documentElement.lang=LANG;{const sl=document.getElementById('hSlogan');if(sl)sl.textContent=t('slogan')}document.querySelectorAll('[data-i]').forEach(el=>{el.innerHTML=t(el.dataset.i,{n:MIN_LEVELS})});document.querySelectorAll('[data-ph]').forEach(el=>el.placeholder=t(el.dataset.ph))}
